// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/admin/config/overview", wrapper.GetAdminConfigOverview)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/auth/logout", wrapper.LogoutAdmin)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/auth/session", wrapper.GetAuthSession)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/customers", wrapper.ListCustomers)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/customers/{customer_id}", wrapper.GetCustomer)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/customers/{customer_id}", wrapper.UpdateCustomer)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/customers/{customer_id}/events", wrapper.ListCustomerEvents)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/customers/{customer_id}/stage", wrapper.SetCustomerStage)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/customers/{customer_id}/tags/{tag_id}", wrapper.RemoveCustomerTag)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/customers/{customer_id}/tags/{tag_id}", wrapper.AddCustomerTag)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/identity/bind", wrapper.BindIdentity)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/identity/ingest", wrapper.IngestIdentityEvent)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/identity/resolve", wrapper.ResolveIdentity)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/stages", wrapper.ListStages)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/stages", wrapper.CreateStage)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/stages/{stage_id}", wrapper.RenameStage)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/tags", wrapper.ListTags)
	})

	return r
}

