// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// List non-secret configuration readiness
	// (GET /api/v1/admin/config/overview)
	GetAdminConfigOverview(ctx context.Context, request GetAdminConfigOverviewRequestObject) (GetAdminConfigOverviewResponseObject, error)
	// Invalidate the current admin session
	// (POST /api/v1/auth/logout)
	LogoutAdmin(ctx context.Context, request LogoutAdminRequestObject) (LogoutAdminResponseObject, error)
	// Return the authenticated admin principal
	// (GET /api/v1/auth/session)
	GetAuthSession(ctx context.Context, request GetAuthSessionRequestObject) (GetAuthSessionResponseObject, error)
	// List customers using a keyset cursor
	// (GET /api/v1/customers)
	ListCustomers(ctx context.Context, request ListCustomersRequestObject) (ListCustomersResponseObject, error)
	// Get a channel-neutral customer by OneID
	// (GET /api/v1/customers/{customer_id})
	GetCustomer(ctx context.Context, request GetCustomerRequestObject) (GetCustomerResponseObject, error)
	// Update customer-owned profile fields
	// (PATCH /api/v1/customers/{customer_id})
	UpdateCustomer(ctx context.Context, request UpdateCustomerRequestObject) (UpdateCustomerResponseObject, error)
	// List append-only customer events using a keyset cursor
	// (GET /api/v1/customers/{customer_id}/events)
	ListCustomerEvents(ctx context.Context, request ListCustomerEventsRequestObject) (ListCustomerEventsResponseObject, error)
	// Set or clear a customer's stage
	// (PUT /api/v1/customers/{customer_id}/stage)
	SetCustomerStage(ctx context.Context, request SetCustomerStageRequestObject) (SetCustomerStageResponseObject, error)
	// Idempotently remove one local tag from a customer
	// (DELETE /api/v1/customers/{customer_id}/tags/{tag_id})
	RemoveCustomerTag(ctx context.Context, request RemoveCustomerTagRequestObject) (RemoveCustomerTagResponseObject, error)
	// Idempotently apply one local tag to a customer
	// (PUT /api/v1/customers/{customer_id}/tags/{tag_id})
	AddCustomerTag(ctx context.Context, request AddCustomerTagRequestObject) (AddCustomerTagResponseObject, error)
	// Bind a scoped identity to a channel-neutral customer
	// (POST /api/v1/identity/bind)
	BindIdentity(ctx context.Context, request BindIdentityRequestObject) (BindIdentityResponseObject, error)
	// Attribute or persist an external event without guessing identity
	// (POST /api/v1/identity/ingest)
	IngestIdentityEvent(ctx context.Context, request IngestIdentityEventRequestObject) (IngestIdentityEventResponseObject, error)
	// Resolve one scoped identity without implicit creation
	// (POST /api/v1/identity/resolve)
	ResolveIdentity(ctx context.Context, request ResolveIdentityRequestObject) (ResolveIdentityResponseObject, error)
	// List global customer stages in deterministic order
	// (GET /api/v1/stages)
	ListStages(ctx context.Context, request ListStagesRequestObject) (ListStagesResponseObject, error)
	// Create one global customer stage
	// (POST /api/v1/stages)
	CreateStage(ctx context.Context, request CreateStageRequestObject) (CreateStageResponseObject, error)
	// Rename one global customer stage
	// (PATCH /api/v1/stages/{stage_id})
	RenameStage(ctx context.Context, request RenameStageRequestObject) (RenameStageResponseObject, error)
	// List the local tag catalog in deterministic order
	// (GET /api/v1/tags)
	ListTags(ctx context.Context, request ListTagsRequestObject) (ListTagsResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

